function permutations(array):
    if length(array) == 0:
        return [[]]

    allPerms = []

    for i = 0 to length(array) - 1:
        element = array[i]
        remaining = array without element

        for each perm in permutations(remaining):
            allPerms.append([element] + perm)

    return allPerms

function tsp(cities):
    if length(cities) == 1:
        return [cities[0]]

    shortestPath = null
    shortestDistance = infinity

    for each permutation in permutations(cities):
        distance = calculateDistance(permutation)

        if distance < shortestDistance:
            shortestDistance = distance
            shortestPath = permutation

    return shortestPath

function findAnagrams(string):
    if length(string) == 0:
        return [""]

    anagrams = []

    for i = 0 to length(string) - 1:
        char = string[i]
        remaining = string without char

        for each anagram in findAnagrams(remaining):
            anagrams.append(char + anagram)

    return anagrams

function optimalSchedule(tasks):
    allSchedules = permutations(tasks)
    bestSchedule = null
    bestScore = -infinity

    for each schedule in allSchedules:
        score = evaluateSchedule(schedule)

        if score > bestScore:
            bestScore = score
            bestSchedule = schedule

    return bestSchedule
